_C = [(b, re.compile(p, re.I)) for b, p in RULES]


def tag_bloc(text, typ='', fallback=None):
    t = text or ''
    for b, rx in _C:
        if rx.search(t):
            return b
    if fallback:
        return fallback
    if typ == 'Party':
        return 'Party and leadership'
    if typ in ('PAC', 'Political committee', 'Super PAC'):
        return 'Unresolved PAC'
    return 'Large individual donors'
